// Des: Find, launch, stop local Chrome or Edge for CDP
// Flo: find exe > dedicated profile dir > spawn with port 0 > read DevToolsActivePort > list targets over /json > kill by child handle
// I/O: config paths (caller) > Brow (child, port, profile); page websocket path; stop frees everything
// ===================================================================
const std = @import("std"); const net = std.Io.net; const mem = std.mem; const builtin = @import("builtin"); const cdp = @import("nt-cdpz-sock.zig");
const CF = .{ .actf = "DevToolsActivePort", .winp = @as([]const []const u8, &.{ "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe", "C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe", "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe", "C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe" }), .linp = @as([]const []const u8, &.{ "/usr/bin/google-chrome", "/usr/bin/google-chrome-stable", "/usr/bin/chromium", "/usr/bin/chromium-browser", "/snap/bin/chromium", "/usr/bin/microsoft-edge" }), .macp = @as([]const []const u8, &.{ "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge" }), .poll = 100, .maxr = 1 << 20 };
const winx = struct { extern "kernel32" fn GetProcessId(h: std.os.windows.HANDLE) callconv(.winapi) u32; };
pub const Brow = struct { child: std.process.Child, port: u16, prof: []u8, gpaz: std.mem.Allocator, iozz: std.Io,
pub fn stop(self: *Brow) void { const soft = self.closeSoft(); var tries: u32 = 0; while (!portDead(self.gpaz, self.iozz, self.port) and tries < 50) : (tries += 1) std.Io.sleep(self.iozz, .fromMilliseconds(100), .awake) catch {}; if (soft and portDead(self.gpaz, self.iozz, self.port)) { _ = self.child.wait(self.iozz) catch {}; } else { self.killHard(); self.child.kill(self.iozz); } self.gpaz.free(self.prof); }
fn closeSoft(self: *Brow) bool { const body = httpGet(self.gpaz, self.iozz, self.port, "/json/version") catch return false; defer self.gpaz.free(body); var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const valu = std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), body, .{}) catch return false; if (valu != .object) return false; const wsu = valu.object.get("webSocketDebuggerUrl") orelse return false; if (wsu != .string) return false; const sep = mem.find(u8, wsu.string, "/devtools/") orelse return false; const conn = cdp.connect(self.gpaz, self.iozz, self.port, wsu.string[sep..], 3000) catch return false; defer conn.close(); const rsp = conn.call(self.gpaz, "Browser.close", "", 3000) catch return false; self.gpaz.free(rsp); return true; }
fn killHard(self: *Brow) void { if (builtin.os.tag == .windows) { var buf: [16]u8 = undefined; const pid = std.fmt.bufPrint(&buf, "{d}", .{winx.GetProcessId(self.child.id.?)}) catch return; var kch = std.process.spawn(self.iozz, .{ .argv = &.{ "taskkill", "/PID", pid, "/T", "/F" }, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore }) catch return; _ = kch.wait(self.iozz) catch {}; } } };
fn treeKill(iozz: std.Io, child: *std.process.Child) void { if (builtin.os.tag != .windows) return; const hid = child.id orelse return; var buf: [16]u8 = undefined; const pid = std.fmt.bufPrint(&buf, "{d}", .{winx.GetProcessId(hid)}) catch return; var kch = std.process.spawn(iozz, .{ .argv = &.{ "taskkill", "/PID", pid, "/T", "/F" }, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore }) catch return; _ = kch.wait(iozz) catch {}; }
fn exists(iozz: std.Io, path: []const u8) bool { _ = std.Io.Dir.cwd().statFile(iozz, path, .{}) catch return false; return true; }
pub fn exeFind(gpaz: std.mem.Allocator, iozz: std.Io, pref: []const u8) !?[]u8 { if (pref.len > 0) { if (exists(iozz, pref)) return try gpaz.dupe(u8, pref); return null; } const list = switch (builtin.os.tag) { .windows => CF.winp, .macos => CF.macp, else => CF.linp }; for (list) |path| if (exists(iozz, path)) return try gpaz.dupe(u8, path); return null; }
pub fn httpGet(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, path: []const u8) ![]u8 { var addr = try net.IpAddress.parse("127.0.0.1", port); const strm = try addr.connect(iozz, .{ .mode = .stream }); defer strm.close(iozz); var wbuf: [512]u8 = undefined; var wrt = strm.writer(iozz, &wbuf); try wrt.interface.print("GET {s} HTTP/1.1\r\nHost: 127.0.0.1:{d}\r\nAccept: */*\r\nConnection: close\r\n\r\n", .{ path, port }); try wrt.interface.flush(); var rbuf: [4096]u8 = undefined; var rdr = strm.reader(iozz, &rbuf); const rd = &rdr.interface; const first = try rd.takeDelimiterInclusive('\n'); if (mem.find(u8, first, " 200") == null) return error.BadReply; var clen: ?usize = null; while (true) { const line = try rd.takeDelimiterInclusive('\n'); if (line.len <= 2) break; if (std.ascii.startsWithIgnoreCase(line, "content-length:")) clen = std.fmt.parseInt(usize, mem.trim(u8, line[15..], " \r\n"), 10) catch null; } if (clen) |cnt| { if (cnt > CF.maxr) return error.BadReply; const body = try gpaz.alloc(u8, cnt); errdefer gpaz.free(body); try rd.readSliceAll(body); return body; } return rd.allocRemaining(gpaz, .limited(CF.maxr)); }
pub const Wind = struct { widt: u32 = 0, high: u32 = 0, scal: f64 = 0, left: i32 = 0 };
pub fn windArgz(aren: std.mem.Allocator, head: bool, wind: Wind) ![]const []const u8 { var list: std.ArrayList([]const u8) = .empty; if (head) return list.items; try list.append(aren, try std.fmt.allocPrint(aren, "--window-position={d},0", .{wind.left})); if (wind.widt > 0 and wind.high > 0) try list.append(aren, try std.fmt.allocPrint(aren, "--window-size={d},{d}", .{ wind.widt, wind.high })); if (wind.scal > 0) try list.append(aren, try std.fmt.allocPrint(aren, "--force-device-scale-factor={d}", .{wind.scal})); return list.items; }
pub fn launch(gpaz: std.mem.Allocator, iozz: std.Io, exe: []const u8, prof: []const u8, head: bool, wind: Wind, mill: u32) !Brow { try std.Io.Dir.cwd().createDirPath(iozz, prof); const actp = try std.fs.path.join(gpaz, &.{ prof, CF.actf }); defer gpaz.free(actp); std.Io.Dir.cwd().deleteFile(iozz, actp) catch {}; var argv: std.ArrayList([]const u8) = .empty; defer argv.deinit(gpaz); const udd = try std.fmt.allocPrint(gpaz, "--user-data-dir={s}", .{prof}); defer gpaz.free(udd); try argv.appendSlice(gpaz, &.{ exe, "--remote-debugging-port=0", udd, "--no-first-run", "--no-default-browser-check", "--disable-background-networking", "--disable-sync", "--disable-gpu", "--mute-audio" }); if (head) try argv.append(gpaz, "--headless=new"); var wina = std.heap.ArenaAllocator.init(gpaz); defer wina.deinit(); try argv.appendSlice(gpaz, try windArgz(wina.allocator(), head, wind)); try argv.append(gpaz, "about:blank"); var child = try std.process.spawn(iozz, .{ .argv = argv.items, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore }); errdefer { treeKill(iozz, &child); child.kill(iozz); } var waited: u32 = 0; while (waited <= mill) : (waited += CF.poll) { if (std.Io.Dir.cwd().readFileAlloc(iozz, actp, gpaz, .limited(512))) |txt| { defer gpaz.free(txt); var itr = mem.splitScalar(u8, txt, '\n'); const pstr = mem.trim(u8, itr.next() orelse "", " \r"); if (std.fmt.parseInt(u16, pstr, 10)) |port| { if (port > 0) return .{ .child = child, .port = port, .prof = try gpaz.dupe(u8, prof), .gpaz = gpaz, .iozz = iozz }; } else |_| {} } else |_| {} std.Io.sleep(iozz, .fromMilliseconds(CF.poll), .awake) catch {}; } return error.LaunchTimeout; }
pub fn pageWs(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, mill: u32) ![]u8 { var waited: u32 = 0; while (waited <= mill) : (waited += CF.poll * 2) { if (httpGet(gpaz, iozz, port, "/json")) |body| { defer gpaz.free(body); var aren = std.heap.ArenaAllocator.init(gpaz); defer aren.deinit(); if (std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), body, .{})) |valu| { if (valu == .array) { for (valu.array.items) |item| { if (item != .object) continue; const typ = item.object.get("type") orelse continue; if (typ != .string or !mem.eql(u8, typ.string, "page")) continue; const wsu = item.object.get("webSocketDebuggerUrl") orelse continue; if (wsu != .string) continue; const sep = mem.find(u8, wsu.string, "/devtools/") orelse continue; return gpaz.dupe(u8, wsu.string[sep..]); } } } else |_| {} } else |_| {} std.Io.sleep(iozz, .fromMilliseconds(CF.poll * 2), .awake) catch {}; } return error.NoPage; }
pub fn portDead(gpaz: std.mem.Allocator, iozz: std.Io, port: u16) bool { _ = gpaz; var addr = net.IpAddress.parse("127.0.0.1", port) catch return true; const strm = addr.connect(iozz, .{ .mode = .stream }) catch return true; strm.close(iozz); return false; }
